 */

 `timescale 1ns / 1ps
 module optibolt_controller_tb();
 
     // --- Sygnały testowe ---
     logic clk400;
     logic rst_n;
     logic [3:0] oversampling;
     logic [3:0] bit_rate;
 
     // Połączenie światłowodowe (wirtualne)
     logic rx_manchester;
     logic tx_manchester;
 
     // RX Interfejs
     logic rx_enable;
     logic rx_empty, rx_full;
     logic [7:0] data_out;
     logic [2:0] msg_type_out;
     logic parity_error, manchester_code_error, preamble_error;
 
     // TX Interfejs
     logic tx_enable;
     logic [2:0] tx_msg_type;
     logic [7:0] tx_data;
     logic tx_empty, tx_full;
 
     // --- Instancja testowanego kontrolera (DUT) ---
     optibolt_controller dut (
         .clk400(clk400),
         .rst_n(rst_n),
         .oversampling(oversampling),
         .bit_rate(bit_rate),
         .rx_manchester(rx_manchester),
         .tx_manchester(tx_manchester),
         .rx_enable(rx_enable),
         .rx_empty(rx_empty),
         .rx_full(rx_full),
         .data_out(data_out),
         .msg_type_out(msg_type_out),
         .parity_error(parity_error),
         .manchester_code_error(manchester_code_error), 
         .preamble_error(preamble_error),
         .tx_enable(tx_enable),
         .tx_msg_type(tx_msg_type),
         .tx_data(tx_data),
         .tx_empty(tx_empty),
         .tx_full(tx_full)
     );
 
     // --- Symulacja kabla światłowodowego ---
     // Usunięte sztuczne opóźnienie, które psuło fazę!
     assign rx_manchester = (tx_manchester === 1'bx) ? 1'b1 : tx_manchester;
 
     // --- Generator Zegara (400 MHz -> okres 2.5 ns) ---
     initial begin
         clk400 = 0;
         forever #1.25 clk400 = ~clk400;
     end
 
     // =========================================================
     // ZADANIA TESTOWE (TASKS)
     // =========================================================
 
     task send_byte(input logic [2:0] msg, input logic [7:0] data);
         begin
             @(posedge clk400);
             wait(!tx_full); 
             
             tx_msg_type = msg;
             tx_data = data;
             tx_enable = 1'b1;
             
             @(posedge clk400);
             tx_enable = 1'b0; 
             
             $display("[TX] Wysłano do bufora: Typ = %b, Znak = '%c' (0x%h)", msg, data, data);
         end
     endtask
 
     task wait_and_check_byte(input logic [2:0] expected_msg, input logic [7:0] expected_data);
         begin
             fork
                 begin
                     wait(!rx_empty); 
                 end
                 begin
                     #1500000; // Wydłużony Timeout na wypadek wolnego bit rate'u
                     $error("[FATAL] Timeout! Brak danych w RX FIFO.");
                     $finish;
                 end
             join_any
             disable fork;
 
             // Odczyt z FIFO
             @(posedge clk400);
             rx_enable = 1'b1;
             @(posedge clk400);
             rx_enable = 1'b0;
             @(posedge clk400); 
 
             // Asercje
             assert (data_out === expected_data) 
                 $display("[RX-OK] Dane poprawne. Odebrano: '%c'", data_out);
             else 
                 $error("[RX-BŁĄD] Złe dane! Oczekiwano: '%c' (0x%h), Otrzymano: '%c' (0x%h)", expected_data, expected_data, data_out, data_out);
 
             assert (msg_type_out === expected_msg) 
                 $display("[RX-OK] Nagłówek poprawny. Odebrano: %b", msg_type_out);
             else 
                 $error("[RX-BŁĄD] Zły nagłówek! Oczekiwano: %b, Otrzymano: %b", expected_msg, msg_type_out);
 
             assert (parity_error === 1'b0) 
                 $display("[RX-OK] Parzystość pomyślna (Brak błędu).");
             else 
                 $error("[RX-BŁĄD] Wykryto błąd parzystości!");
                 
             $display("--------------------------------------------------");
         end
     endtask
 
     // =========================================================
     // SCENARIUSZ GŁÓWNY
     // =========================================================
     initial begin
         rst_n = 0;
         rx_enable = 0;
         tx_enable = 0;
         tx_msg_type = 0;
         tx_data = 0;
         
         oversampling = 4'b0000; // POPRAWIONY KOD 8X (zamiast liczby 8)
         bit_rate = 4'd10;    
         
         $display("==================================================");
         $display("   ROZPOCZĘCIE TESTÓW OPTIBOLT CONTROLLER         ");
         $display("==================================================");
 
         #100;
         rst_n = 1;
         #50000; // Czekamy chwilę aż układ się ustatkuje
         
         $display("\n---> TEST 1: Pojedynczy znak <---");
         send_byte(3'b100, 8'h41); 
         wait_and_check_byte(3'b100, 8'h41);
 
         $display("\n---> TEST 2: Transmisja seryjna (Test FIFO) <---");
         send_byte(3'b100, "T");
         send_byte(3'b100, "E");
         send_byte(3'b100, "S");
         send_byte(3'b100, "T");
         
         wait_and_check_byte(3'b100, "T");
         wait_and_check_byte(3'b100, "E");
         wait_and_check_byte(3'b100, "S");
         wait_and_check_byte(3'b100, "T");
 
         $display("\n---> TEST 3: Wstrzykiwanie błędów i Error Recovery <---");
         $display("[INFO] Nadaję znak 'X', ale zaraz uszkodzę kabel...");
         send_byte(3'b100, "X");
 
         #25000; 
         force rx_manchester = 1'b0; 
         #20000;                     
         release rx_manchester;      
         $display("[INFO] Zakłócenie zakończone. Odbiornik powinien teraz odrzucić śmieci.");
 
         fork
             begin
                 wait(manchester_code_error || preamble_error); 
                 $display("[RX-OK] Sukces! Odbiornik prawidłowo wykrył zakłócenie i zapalił flagę błędu.");
             end
             begin
                 #100000;
                 $error("[FATAL] Odbiornik nie zauważył błędu! Przyjął uszkodzone dane.");
             end
         join_any
         disable fork;

        #300000; // Czekamy chwilę, aby ew. fałszywa ramka zdążyła się zapisać
        if (!rx_empty) begin
            $display("[INFO] Wykryto fałszywą ramkę w FIFO (Ghost Frame) - Czyszczenie bufora...");
            @(posedge clk400);
            rx_enable <= 1'b1;
            @(posedge clk400);
            rx_enable <= 1'b0;
            @(posedge clk400);
        end
 
         $display("\n[INFO] Sprawdzam, czy odbiornik wrócił do trybu szukania (Searching)...");
         send_byte(3'b100, "Y");
         wait_and_check_byte(3'b100, "Y");
         $display("[RX-OK] Wyśmienicie! Odbiornik otrzepał się z błędów i odebrał 'Y'.");
 
         $display("==================================================");
         $display("   WERYFIKACJA ZAKOŃCZONA SUKCESEM!               ");
         $display("==================================================");
         
         #1000;
         $finish; 
     end
 
 endmodule